import { useQuery } from "@tanstack/react-query";
import { AdminSidebar } from "@/components/AdminSidebar";
import { SidebarProvider, SidebarTrigger } from "@/components/ui/sidebar";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { useState } from "react";
import type { Banner } from "@shared/schema";

export default function BannersPage() {
  const [imageFile, setImageFile] = useState<File | null>(null);

  const { data: banners, isLoading } = useQuery<Banner[]>({
    queryKey: ["/api/banners"],
  });

  return (
    <SidebarProvider>
      <div className="flex h-screen w-full admin-light">
        <AdminSidebar />
        <div className="flex flex-col flex-1 overflow-hidden">
          <header className="flex items-center justify-between p-4 border-b bg-white">
            <SidebarTrigger data-testid="button-sidebar-toggle" />
            <h1 className="text-2xl font-bold">Slideshow / Banner</h1>
            <div className="w-10" />
          </header>

          <main className="flex-1 overflow-auto p-6">
            <div className="max-w-4xl mx-auto space-y-8">
              {/* Upload Section */}
              <div className="bg-white rounded-lg border p-6">
                <h2 className="text-lg font-semibold mb-4">Tambah Banner</h2>
                <div className="space-y-4">
                  <div>
                    <Label>Gambar</Label>
                    <div className="flex gap-2 items-center">
                      <Input
                        type="file"
                        accept="image/*"
                        data-testid="input-banner"
                        onChange={(e) => setImageFile(e.target.files?.[0] || null)}
                      />
                      <Button className="bg-blue-600 hover:bg-blue-700" data-testid="button-upload">
                        Tambah
                      </Button>
                    </div>
                  </div>
                </div>
              </div>

              {/* Banner List */}
              <div className="bg-white rounded-lg border">
                <div className="p-6 border-b">
                  <h2 className="text-lg font-semibold">Daftar Banner</h2>
                </div>
                <div className="divide-y">
                  {isLoading ? (
                    <div className="p-8 text-center text-gray-500">Loading...</div>
                  ) : banners && banners.length > 0 ? (
                    banners.map((banner) => (
                      <div
                        key={banner.id}
                        data-testid={`banner-${banner.id}`}
                        className="p-6 flex items-center justify-between"
                      >
                        <div className="flex items-center gap-4">
                          <span className="text-gray-600 font-medium w-12">
                            {String(banner.order).padStart(2, "0")}
                          </span>
                          <img
                            src={banner.imageUrl}
                            alt={`Banner ${banner.order}`}
                            className="w-48 h-24 object-cover rounded"
                          />
                        </div>
                        <div className="flex gap-2">
                          <span className="text-gray-500 text-sm">Aksi</span>
                          <Button
                            size="sm"
                            variant="destructive"
                            data-testid={`button-delete-${banner.id}`}
                          >
                            Hapus
                          </Button>
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="p-8 text-center text-gray-500">
                      Belum ada banner
                    </div>
                  )}
                </div>
              </div>
            </div>
          </main>
        </div>
      </div>
    </SidebarProvider>
  );
}

