                >
                  Batal
                </button>
                <button
                  onClick={handleConfirmPurchase}
                  disabled={purchaseMutation.isPending}
                  data-testid="button-confirm-purchase"
                  className="flex-1 h-12 rounded-lg holographic-btn font-bold"
                >
                  {purchaseMutation.isPending ? "Memproses..." : "Konfirmasi"}
                </button>
              </div>
            </DialogContent>
          </Dialog>

          {/* Payment Methods */}
          <div className="pt-6">
            <h2 className="text-lg font-bold mb-4">Metode Pembayaran</h2>
            <div className="grid grid-cols-3 gap-4">
              <div className="bg-white rounded p-2 flex items-center justify-center h-12">
                <span className="text-blue-600 font-bold text-xs">BCA</span>
              </div>
              <div className="bg-white rounded p-2 flex items-center justify-center h-12">
                <span className="text-orange-600 font-bold text-xs">BNI</span>
              </div>
              <div className="bg-white rounded p-2 flex items-center justify-center h-12">
                <span className="text-blue-500 font-bold text-xs">Mandiri</span>
              </div>
              <div className="bg-white rounded p-2 flex items-center justify-center h-12">
                <span className="text-blue-700 font-bold text-xs">BSI</span>
              </div>
              <div className="bg-white rounded p-2 flex items-center justify-center h-12">
                <span className="text-blue-800 font-bold text-xs">Bank BJB</span>
