  return (
    <Comp
      data-slot="sidebar-menu-sub-button"
      data-sidebar="menu-sub-button"
      data-size={size}
      data-active={isActive}
      className={cn(
        "text-sidebar-foreground ring-sidebar-ring hover:bg-sidebar-accent hover:text-sidebar-accent-foreground active:bg-sidebar-accent active:text-sidebar-accent-foreground [&>svg]:text-sidebar-accent-foreground flex h-7 min-w-0 -translate-x-px items-center gap-2 overflow-hidden rounded-md px-2 outline outline-2 outline-transparent outline-offset-2 focus-visible:ring-2 disabled:pointer-events-none disabled:opacity-50 aria-disabled:pointer-events-none aria-disabled:opacity-50 [&>span:last-child]:truncate [&>svg]:size-4 [&>svg]:shrink-0",
        "data-[active=true]:bg-sidebar-accent data-[active=true]:text-sidebar-accent-foreground",
        size === "sm" && "text-xs",
        size === "md" && "text-sm",
        "group-data-[collapsible=icon]:hidden",
        className
      )}
      {...props}
    />
  )
}

export {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupAction,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarInput,
  SidebarInset,
  SidebarMenu,
  SidebarMenuAction,
  SidebarMenuBadge,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarMenuSkeleton,
  SidebarMenuSub,
  SidebarMenuSubButton,
  SidebarMenuSubItem,
  SidebarProvider,
  SidebarRail,
  SidebarSeparator,
  SidebarTrigger,
  useSidebar,
}

client/src/components/ui/toggle-group.ts.content:
"use client"

import * as React from "react"
import * as ToggleGroupPrimitive from "@radix-ui/react-toggle-group"
import { type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"
import { toggleVariants } from "@/components/ui/toggle"

const ToggleGroupContext = React.createContext<
  VariantProps<typeof toggleVariants>
>({
  size: "default",
  variant: "default",
})

const ToggleGroup = React.forwardRef<
  React.ElementRef<typeof ToggleGroupPrimitive.Root>,
  React.ComponentPropsWithoutRef<typeof ToggleGroupPrimitive.Root> &
    VariantProps<typeof toggleVariants>
>(({ className, variant, size, children, ...props }, ref) => (
  <ToggleGroupPrimitive.Root
    ref={ref}
    className={cn("flex items-center justify-center gap-1", className)}
    {...props}
  >
    <ToggleGroupContext.Provider value={{ variant, size }}>
      {children}
    </ToggleGroupContext.Provider>
  </ToggleGroupPrimitive.Root>
))

ToggleGroup.displayName = ToggleGroupPrimitive.Root.displayName

const ToggleGroupItem = React.forwardRef<
  React.ElementRef<typeof ToggleGroupPrimitive.Item>,
  React.ComponentPropsWithoutRef<typeof ToggleGroupPrimitive.Item> &
    VariantProps<typeof toggleVariants>
>(({ className, children, variant, size, ...props }, ref) => {
  const context = React.useContext(ToggleGroupContext)

  return (
    <ToggleGroupPrimitive.Item
      ref={ref}
      className={cn(
        toggleVariants({
          variant: context.variant || variant,
          size: context.size || size,
        }),
        className
      )}
      {...props}
    >
      {children}
    </ToggleGroupPrimitive.Item>
  )
})

ToggleGroupItem.displayName = ToggleGroupPrimitive.Item.displayName

export { ToggleGroup, ToggleGroupItem }

client/src/pages/admin/CreateEventPage.t.content:
import { AdminSidebar } from "@/components/AdminSidebar";
import { SidebarProvider, SidebarTrigger } from "@/components/ui/sidebar";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { useState } from "react";
import { ImagePlus } from "lucide-react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { insertEventSchema, type InsertEvent } from "@shared/schema";
import { z } from "zod";
import { useMutation } from "@tanstack/react-query";
import { queryClient } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { useLocation } from "wouter";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

const formSchema = z.object({
  name: z.string().min(1, "Event name is required"),
  imageUrl: z.string().url("Image URL must be a valid URL").min(1, "Image URL is required"),
  description: z.string().min(1, "Description is required"),
  price: z.number().int().positive("Price must be a positive number"),
  ticketCount: z.number().int().positive("Ticket count must be a positive number"),
  prize: z.string().min(1, "Prize description is required"),
  hadiah: z.number().int().positive("Prize value must be a positive number"),
  startDate: z.string().min(1, "Start date is required"),
  endDate: z.string().min(1, "End date is required"),
  announcementDate: z.string().min(1, "Announcement date is required"),
  status: z.enum(["aktif", "nonaktif", "selesai"]),
  category: z.string().optional(),
});

type FormData = z.infer<typeof formSchema>;

export default function CreateEventPage() {
  const [, setLocation] = useLocation();
  const { toast } = useToast();

  const { register, handleSubmit, formState: { errors }, setValue } = useForm<FormData>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      name: "",
      description: "",
      price: 0,
      ticketCount: 0,
      prize: "",
      hadiah: 0,
      imageUrl: "",
      status: "aktif",
      category: "other",
    },
  });

  const createMutation = useMutation({
    mutationFn: async (data: FormData) => {
      const response = await fetch("/api/events", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${localStorage.getItem("admin_token")}`,
        },
        body: JSON.stringify(data),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Failed to create event");
      }

      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/events"] });
      toast({
        title: "Event Created",
        description: "Event has been created successfully",
      });
      setLocation("/admin/events");
    },
    onError: (error: Error) => {
      toast({
        variant: "destructive",
        title: "Failed to create event",
        description: error.message,
      });
    },
  });

  const onSubmit = (data: FormData) => {
    if (!data.imageUrl) {
      toast({
        variant: "destructive",
        title: "Image URL required",
        description: "Please provide an image URL",
      });
      return;
    }
    createMutation.mutate(data);
  };

  return (
    <SidebarProvider>
      <div className="flex h-screen w-full admin-light">
        <AdminSidebar />
        <div className="flex flex-col flex-1 overflow-hidden">
          <header className="flex items-center justify-between p-4 border-b bg-white">
            <SidebarTrigger data-testid="button-sidebar-toggle" />
            <h1 className="text-2xl font-bold">Buat Event</h1>
            <div className="w-10" />
          </header>

          <main className="flex-1 overflow-auto p-6">
            <form onSubmit={handleSubmit(onSubmit)} className="max-w-4xl mx-auto space-y-6">
              <div className="bg-white rounded-lg border p-6">
                <h2 className="text-xl font-semibold mb-4">Detail Event</h2>

                <div className="space-y-4">
                  <div>
                    <Label htmlFor="name">Nama Event *</Label>
                    <Input
                      id="name"
                      {...register("name")}
                      data-testid="input-name"
                      placeholder="Contoh: Undian Motor Honda"
                    />
                    {errors.name && (
                      <p className="text-red-500 text-sm mt-1">{errors.name.message}</p>
                    )}
                  </div>

                  <div>
                    <Label htmlFor="imageUrl">URL Gambar Event *</Label>
                    <Input
                      id="imageUrl"
                      {...register("imageUrl")}
                      data-testid="input-image-url"
                      placeholder="https://images.unsplash.com/photo-..."
                    />
                    <p className="text-xs text-gray-500 mt-1">
                      Masukkan URL gambar dari sumber eksternal (Unsplash, Imgur, dll)
                    </p>
                    {errors.imageUrl && (
                      <p className="text-red-500 text-sm mt-1">{errors.imageUrl.message}</p>
                    )}
                  </div>

                  <div>
                    <Label htmlFor="description">Deskripsi *</Label>
                    <Textarea
                      id="description"
                      {...register("description")}
                      data-testid="input-description"
                      placeholder="Tulis deskripsi event..."
                      rows={6}
                    />
                    {errors.description && (
                      <p className="text-red-500 text-sm mt-1">{errors.description.message}</p>
                    )}
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <Label htmlFor="price">Harga (Rp) *</Label>
                      <Input
                        id="price"
                        type="number"
                        {...register("price", { valueAsNumber: true })}
                        data-testid="input-price"
                        placeholder="50000"
                      />
                      {errors.price && (
                        <p className="text-red-500 text-sm mt-1">{errors.price.message}</p>
                      )}
                    </div>

                    <div>
                      <Label htmlFor="ticketCount">Jumlah Tiket *</Label>
                      <Input
                        id="ticketCount"
                        type="number"
                        {...register("ticketCount", { valueAsNumber: true })}
                        data-testid="input-ticket-count"
                        placeholder="1000"
                      />
                      {errors.ticketCount && (
                        <p className="text-red-500 text-sm mt-1">{errors.ticketCount.message}</p>
                      )}
                    </div>
                  </div>

                  <div>
                    <Label htmlFor="prize">Hadiah *</Label>
                    <Input
                      id="prize"
                      {...register("prize")}
                      data-testid="input-prize"
                      placeholder="Motor Honda Beat 2025"
                    />
                    {errors.prize && (
                      <p className="text-red-500 text-sm mt-1">{errors.prize.message}</p>
                    )}
                  </div>

                  <div>
                    <Label htmlFor="hadiah">Nilai Hadiah (Rp) *</Label>
                    <Input
                      id="hadiah"
                      type="number"
                      {...register("hadiah", { valueAsNumber: true })}
                      data-testid="input-hadiah-value"
                      placeholder="20000000"
                    />
                    {errors.hadiah && (
                      <p className="text-red-500 text-sm mt-1">{errors.hadiah.message}</p>
                    )}
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div>
                      <Label htmlFor="startDate">Tanggal Mulai *</Label>
                      <Input
                        id="startDate"
                        type="datetime-local"
                        {...register("startDate")}
                        data-testid="input-start-date"
                      />
                      {errors.startDate && (
                        <p className="text-red-500 text-sm mt-1">{errors.startDate.message}</p>
                      )}
                    </div>

                    <div>
                      <Label htmlFor="endDate">Tanggal Berakhir *</Label>
                      <Input
                        id="endDate"
                        type="datetime-local"
                        {...register("endDate")}
                        data-testid="input-end-date"
                      />
                      {errors.endDate && (
                        <p className="text-red-500 text-sm mt-1">{errors.endDate.message}</p>
                      )}
                    </div>

                    <div>
                      <Label htmlFor="announcementDate">Tanggal Pengumuman *</Label>
                      <Input
                        id="announcementDate"
                        type="datetime-local"
                        {...register("announcementDate")}
                        data-testid="input-announcement-date"
                      />
                      {errors.announcementDate && (
                        <p className="text-red-500 text-sm mt-1">{errors.announcementDate.message}</p>
                      )}
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <Label htmlFor="status">Status *</Label>
                      <Select 
                        defaultValue="aktif" 
                        onValueChange={(value) => setValue("status", value as "aktif" | "selesai" | "nonaktif")}
                      >
                        <SelectTrigger data-testid="select-status">
                          <SelectValue placeholder="Pilih status" />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="aktif">Aktif</SelectItem>
                          <SelectItem value="nonaktif">Nonaktif</SelectItem>
                          <SelectItem value="selesai">Selesai</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>

                    <div>
                      <Label htmlFor="category">Kategori</Label>
                      <Select 
                        defaultValue="other" 
                        onValueChange={(value) => setValue("category", value)}
                      >
                        <SelectTrigger data-testid="select-category">
                          <SelectValue placeholder="Pilih kategori" />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="motor">Motor</SelectItem>
                          <SelectItem value="mobil">Mobil</SelectItem>
                          <SelectItem value="elektronik">Elektronik</SelectItem>
                          <SelectItem value="voucher">Voucher</SelectItem>
                          <SelectItem value="other">Lainnya</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>
                  </div>

                  <div className="flex gap-3 pt-4">
                    <Button 
                      type="submit" 
                      className="bg-blue-600 hover:bg-blue-700" 
                      data-testid="button-save"
                      disabled={createMutation.isPending}
                    >
                      {createMutation.isPending ? "Menyimpan..." : "Simpan Event"}
                    </Button>
                    <Button 
                      type="button"
                      variant="outline" 
                      onClick={() => setLocation("/admin/events")}
                      data-testid="button-cancel"
                    >
                      Batal
                    </Button>
                  </div>
                </div>
              </div>
            </form>
          </main>
        </div>
      </div>
    </SidebarProvider>
  );
}

