client/src/pages/admin/EventsListPage.ts.content:
import { useQuery, useMutation } from "@tanstack/react-query";
import { AdminSidebar } from "@/components/AdminSidebar";
import { AdminPageHeader } from "@/components/AdminPageHeader";
import { SidebarProvider } from "@/components/ui/sidebar";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Card, CardContent } from "@/components/ui/card";
import { Search, Plus, Edit, Trash2, Eye, TrendingUp, Calendar as CalendarIcon } from "lucide-react";
import { Link } from "wouter";
import { useState } from "react";
import type { Event } from "@shared/schema";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";

export default function EventsListPage() {
  const [searchQuery, setSearchQuery] = useState("");
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [eventToDelete, setEventToDelete] = useState<Event | null>(null);
  const { toast } = useToast();

  const { data: events, isLoading } = useQuery<Event[]>({
    queryKey: ["/api/admin/events"],
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      return apiRequest(`/api/events/${id}`, {
        method: "DELETE",
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/events"] });
      toast({
        title: "Event Dihapus",
        description: "Event berhasil dihapus dari sistem",
      });
      setDeleteDialogOpen(false);
      setEventToDelete(null);
    },
    onError: (error: Error) => {
      toast({
        variant: "destructive",
        title: "Gagal menghapus event",
        description: error.message,
      });
    },
  });

  const handleDeleteClick = (event: Event) => {
    setEventToDelete(event);
    setDeleteDialogOpen(true);
  };

  const confirmDelete = () => {
    if (eventToDelete) {
      deleteMutation.mutate(eventToDelete.id);
    }
  };

  const filteredEvents = events?.filter(event =>
    event.name.toLowerCase().includes(searchQuery.toLowerCase())
  ) || [];

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "aktif":
        return <Badge className="bg-green-500 hover:bg-green-600 text-white border-0" data-testid={`status-aktif`}>Aktif</Badge>;
      case "selesai":
        return <Badge className="bg-gray-500 hover:bg-gray-600 text-white border-0" data-testid={`status-selesai`}>Selesai</Badge>;
      case "nonaktif":
        return <Badge className="bg-red-500 hover:bg-red-600 text-white border-0" data-testid={`status-nonaktif`}>Nonaktif</Badge>;
      default:
        return <Badge variant="secondary">{status}</Badge>;
    }
  };

  return (
    <SidebarProvider>
      <AdminSidebar />
      <div className="flex flex-col flex-1 min-h-screen admin-light bg-gray-50">
        <AdminPageHeader 
            title="Daftar Event"
            description="Kelola semua event undian dan pilih pemenang"
            breadcrumbs={[
              { label: "Home", href: "/admin/dashboard" },
              { label: "Events", href: "/admin/events" },
              { label: "Daftar Event" }
            ]}
            actions={
              <Link href="/admin/events/create">
                <Button data-testid="button-create-event" className="bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 shadow-lg">
                  <Plus className="w-4 h-4 mr-2" />
                  Buat Event Baru
                </Button>
              </Link>
            }
          />

        <div className="flex-1 p-8 overflow-y-auto">
            <div className="max-w-7xl mx-auto space-y-6">
              <Card className="border-0 shadow-lg">
                <CardContent className="p-6">
                  <div className="flex items-center gap-4">
                    <div className="relative flex-1 max-w-md">
                      <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                      <Input
                        type="text"
                        placeholder="Cari nama event..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        data-testid="input-search"
                        className="pl-10 h-11 border-gray-200 focus:border-blue-500 focus:ring-blue-500"
                      />
                    </div>
                    <div className="text-sm text-gray-600">
                      {filteredEvents.length} event ditemukan
                    </div>
                  </div>
                </CardContent>
              </Card>

              <Card className="border-0 shadow-lg overflow-hidden">
                <div className="overflow-x-auto">
                  <Table>
                    <TableHeader>
                      <TableRow className="bg-gray-50 hover:bg-gray-50">
                        <TableHead className="font-semibold text-gray-900">Nama Event</TableHead>
                        <TableHead className="font-semibold text-gray-900">Periode</TableHead>
                        <TableHead className="font-semibold text-gray-900">Status</TableHead>
                        <TableHead className="font-semibold text-gray-900">Harga Tiket</TableHead>
                        <TableHead className="font-semibold text-gray-900">Tiket Terjual</TableHead>
                        <TableHead className="font-semibold text-gray-900">Hadiah</TableHead>
                        <TableHead className="font-semibold text-gray-900 text-right">Aksi</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {isLoading ? (
                        <TableRow>
                          <TableCell colSpan={7} className="text-center py-12">
                            <div className="flex items-center justify-center gap-3">
                              <div className="w-6 h-6 border-2 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
                              <span className="text-gray-600">Memuat data...</span>
                            </div>
                          </TableCell>
                        </TableRow>
                      ) : filteredEvents.length > 0 ? (
                        filteredEvents.map((event) => (
                          <TableRow key={event.id} data-testid={`row-event-${event.id}`} className="hover:bg-gray-50 transition-colors">
                            <TableCell className="font-semibold text-gray-900">{event.name}</TableCell>
                            <TableCell className="text-sm text-gray-600">
                              <div className="flex items-center gap-2">
                                <CalendarIcon className="w-4 h-4 text-gray-400" />
                                <span>{new Date(event.startDate).toLocaleDateString('id-ID', { day: 'numeric', month: 'short' })} - {new Date(event.endDate).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' })}</span>
                              </div>
                            </TableCell>
                            <TableCell>{getStatusBadge(event.status)}</TableCell>
                            <TableCell className="font-semibold text-gray-900">Rp {event.price.toLocaleString('id-ID')}</TableCell>
                            <TableCell>
                              <div className="flex items-center gap-2">
                                <div className="flex-1 max-w-[100px] h-2 bg-gray-200 rounded-full overflow-hidden">
                                  <div 
                                    className="h-full bg-gradient-to-r from-blue-500 to-purple-500 rounded-full transition-all"
                                    style={{ width: `${(event.ticketsReceived / event.ticketCount) * 100}%` }}
                                  />
                                </div>
                                <span className="text-sm font-medium text-gray-700">{event.ticketsReceived}/{event.ticketCount}</span>
                              </div>
                            </TableCell>
                            <TableCell className="font-semibold text-green-600">Rp {event.hadiah.toLocaleString('id-ID')}</TableCell>
                            <TableCell>
                              <div className="flex gap-2 justify-end">
                                <Button 
                                  size="sm" 
                                  variant="outline" 
                                  data-testid={`button-detail-${event.id}`}
                                  className="border-blue-200 text-blue-600 hover:bg-blue-50 hover:border-blue-300"
                                >
                                  <Eye className="w-4 h-4 mr-1" />
                                  Detail
                                </Button>
                                <Button 
                                  size="sm" 
                                  variant="destructive" 
                                  data-testid={`button-delete-${event.id}`}
                                  onClick={() => handleDeleteClick(event)}
                                  disabled={deleteMutation.isPending}
                                  className="bg-red-500 hover:bg-red-600"
                                >
                                  <Trash2 className="w-4 h-4 mr-1" />
                                  Hapus
                                </Button>
                              </div>
                            </TableCell>
                          </TableRow>
                        ))
                      ) : (
                        <TableRow>
                          <TableCell colSpan={7} className="text-center py-12">
                            <div className="flex flex-col items-center gap-3">
                              <div className="w-16 h-16 rounded-full bg-gray-100 flex items-center justify-center">
                                <CalendarIcon className="w-8 h-8 text-gray-400" />
                              </div>
                              <div>
                                <p className="text-gray-900 font-semibold">
                                  {searchQuery ? "Tidak ada event ditemukan" : "Belum ada event"}
                                </p>
                                <p className="text-sm text-gray-500 mt-1">
                                  {searchQuery ? "Coba kata kunci lain" : "Buat event pertama Anda"}
                                </p>
                              </div>
                              {!searchQuery && (
                                <Link href="/admin/events/create">
                                  <Button className="mt-2 bg-blue-600 hover:bg-blue-700">
                                    <Plus className="w-4 h-4 mr-2" />
                                    Buat Event Baru
                                  </Button>
                                </Link>
                              )}
                            </div>
                          </TableCell>
                        </TableRow>
                      )}
                    </TableBody>
                  </Table>
                </div>
              </Card>
          </div>
        </div>
      </div>

      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent className="border-0 shadow-2xl">
          <AlertDialogHeader>
            <AlertDialogTitle className="text-xl font-bold text-gray-900">Hapus Event?</AlertDialogTitle>
            <AlertDialogDescription className="text-gray-600">
              Apakah Anda yakin ingin menghapus event <span className="font-semibold text-gray-900">"{eventToDelete?.name}"</span>? 
              Tindakan ini tidak dapat dibatalkan dan semua data terkait akan hilang.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel data-testid="button-cancel-delete" className="hover:bg-gray-100">Batal</AlertDialogCancel>
            <AlertDialogAction
              onClick={confirmDelete}
              data-testid="button-confirm-delete"
              className="bg-red-600 hover:bg-red-700 text-white"
            >
              {deleteMutation.isPending ? (
                <div className="flex items-center gap-2">
                  <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                  <span>Menghapus...</span>
                </div>
              ) : (
                "Hapus Event"
              )}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </SidebarProvider>
  );
}

