import { useQuery } from "@tanstack/react-query";
import { MobileHeader } from "@/components/MobileHeader";
import { MobileBottomNav } from "@/components/MobileBottomNav";
import { Footer } from "@/components/Footer";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { useState, useEffect } from "react";
import type { Event, Banner, Video } from "@shared/schema";
import { Link } from "wouter";
import logoUrl from "@assets/logo undifest_1763476451738.png";
import banner01Url from "@assets/banner01_1763489481905.jpg";
import undian01Url from "@assets/undian01_1763489504866.png";
import undian02Url from "@assets/undian02_1763489504867.png";
import bankUrl from "@assets/bank_1763489481904.png";
import tombolBeliUrl from "@assets/tombol_beli_1763581173753.png";
import kemensosLogoUrl from "@assets/logo kemensos_1763490013360.png";
import thumbTestimoniUrl from "@assets/thumb-testimoni_1763489504865.png";
import thumbVideoUrl from "@assets/thumb-video_1763489504866.png";
import iconFbUrl from "@assets/icon_fb_1763489481907.png";
import iconIgUrl from "@assets/icon_ig_1763489481907.png";
import iconXUrl from "@assets/icon_x_1763489481912.png";
import iconYoutubeUrl from "@assets/icon_youtube_1763489481912.png";
import iconTiktokUrl from "@assets/icon_tiktok_1763489481910.png";
import iconTelegramUrl from "@assets/icon_telegram_1763489481908.png";
import iconAlamatUrl from "@assets/icon_alamat_1763489481906.png";
import iconTeleponUrl from "@assets/icon_telepon_1763489481909.png";
import iconWAUrl from "@assets/icon_WA_1763489481911.png";

import banner01 from "@assets/banner01.jpg";

export default function HomePage() {
  const [currentSlide, setCurrentSlide] = useState(0);

  const { data: banners, isLoading: bannersLoading } = useQuery<Banner[]>({
    queryKey: ["/api/banners"],
  });

  const { data: events, isLoading: eventsLoading } = useQuery<Event[]>({
    queryKey: ["/api/events"],
  });

  const { data: videos, isLoading: videosLoading } = useQuery<Video[]>({
    queryKey: ["/api/videos"],
  });

  // Helper to get safe banner count (minimum 1 to prevent NaN in modulo)
  const getBannerCount = () => {
    return banners && banners.length > 0 ? banners.length : 1;
  };

  // Reset slide index when banners length changes
  useEffect(() => {
    if (banners && banners.length > 0) {
      setCurrentSlide(prev => prev >= banners.length ? 0 : prev);
    } else {
      setCurrentSlide(0);
    }
  }, [banners]);

  // Auto-rotate banners
  useEffect(() => {
    const bannerCount = getBannerCount();
    const interval = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % bannerCount);
    }, 5000);
    return () => clearInterval(interval);
  }, [banners]);

  const nextSlide = () => {
    const bannerCount = getBannerCount();
    if (bannerCount <= 0) return;
    setCurrentSlide((prev) => (prev + 1) % bannerCount);
  };

  const prevSlide = () => {
    const bannerCount = getBannerCount();
    if (bannerCount <= 0) return;
    setCurrentSlide((prev) => (prev - 1 + bannerCount) % bannerCount);
  };

  // Filter and sort events: Burger King first, then Yamaha NMAX, then others
  const activeEvents = (events?.filter(e => e.status === "aktif") || []).sort((a, b) => {
    if (a.cardTemplate === "burgerKing") return -1;
    if (b.cardTemplate === "burgerKing") return 1;
    if (a.cardTemplate === "yamahaNmax") return -1;
    if (b.cardTemplate === "yamahaNmax") return 1;
    return 0;
  });

  // Helper to get event card image based on cardTemplate or fallback to imageUrl
  const getEventCardImage = (event: Event) => {
    if (event.cardTemplate === "burgerKing") {
      return undian01Url;
    } else if (event.cardTemplate === "yamahaNmax") {
      return undian02Url;
    }
    return event.imageUrl; // Fallback to dynamic imageUrl
  };

  const getEventBorderClass = (event: Event) => {
    if (event.category === "food") {
      return "gradient-border-red";
    }
    return "gradient-border-cyan";
  };

  return (
    <div className="min-h-screen bg-[#ffffff]">
      <div className="max-w-undifest mx-auto pb-20">
        <MobileHeader />

        {/* Banner Carousel */}
        <div className="relative overflow-hidden" data-testid="banner-carousel">
          <div className="relative">
            {bannersLoading ? (
              <div className="h-56 bg-gray-800/50 animate-pulse" />
            ) : banners && banners.length > 0 ? (
              <img
                src={banner01}
                alt={`Banner ${currentSlide + 1}`}
                className="w-full h-auto"
              />
            ) : (
              <img
                src={banner01Url}
                alt="Default Banner"
                className="w-full h-auto"
              />
            )}
          </div>
          {!bannersLoading && (
            <>
              <button
                onClick={prevSlide}
                data-testid="button-prev-slide"
                className="absolute left-3 top-1/2 -translate-y-1/2 bg-white/20 hover:bg-white/30 text-white p-2 rounded-full transition-all backdrop-blur-sm"
              >
                <ChevronLeft className="w-6 h-6" />
              </button>
              <button
                onClick={nextSlide}
                data-testid="button-next-slide"
                className="absolute right-3 top-1/2 -translate-y-1/2 bg-white/20 hover:bg-white/30 text-white p-2 rounded-full transition-all backdrop-blur-sm"
              >
                <ChevronRight className="w-6 h-6" />
              </button>
            </>
          )}
        </div>

        {/* Events Section - Dynamic rendering with cardTemplate support */}
        <div className="px-4 py-6 bg-[#16202a]">
          <h2 className="text-xl font-bold text-white mb-4">Pilih & Beli Undian</h2>
          <div className="space-y-4">
            {eventsLoading ? (
              <>
                <div className="h-44 bg-gray-800/50 rounded-xl animate-pulse" />
                <div className="h-44 bg-gray-800/50 rounded-xl animate-pulse" />
              </>
            ) : activeEvents.length > 0 ? (
              activeEvents.map((event) => {
                const cardImageUrl = getEventCardImage(event);
                const borderClass = getEventBorderClass(event);
                const isTemplateCard = event.cardTemplate === "burgerKing" || event.cardTemplate === "yamahaNmax";

                return (
                  <Link key={event.id} href={`/event/${event.id}`}>
                    <div 
                      data-testid={`event-card-${event.id}`}
                      className={`${borderClass} cursor-pointer group relative`}
                    >
                      <div className="bg-transparent rounded-2xl overflow-hidden hover-elevate transition-all">
                        {isTemplateCard ? (
                          // Template card: display complete template image with button overlay
                          (<div className="relative">
                            <img
                              src={cardImageUrl}
                              alt={event.name}
                              className="w-full h-auto pb-5"
                            />
                            <button 
                              data-testid={`button-buy-${event.id}`}
                              className="absolute bottom-4 right-4"
                            >
                              <img src={tombolBeliUrl} alt="Beli" className="h-10 mt-[13px] mb-[13px]" />
                            </button>
                          </div>)
                        ) : (
                          // Dynamic event: render with event data
                          (<div className="relative bg-gradient-to-br from-[#1e3a52] via-[#2a4a6a] to-[#4a3858] min-h-[180px] overflow-hidden">
                            <div className="p-5 pb-16 flex items-start justify-between gap-4">
                              <div className="flex-1 z-10">
                                <h3 className="text-white font-bold text-base leading-tight mb-1">{event.name}</h3>
                                <p className="text-sm text-white/90 leading-snug">{event.description}</p>
                              </div>
                              <img
                                src={cardImageUrl}
                                alt={event.name}
                                className="w-44 h-36 object-contain flex-shrink-0 z-10"
                              />
                            </div>
                            <div className="absolute bottom-4 left-4 right-4 flex items-center justify-between z-20">
                              <div className="flex items-center gap-2">
                                <svg className="w-6 h-6 text-pink-400" fill="currentColor" viewBox="0 0 24 24">
                                  <path d="M4 4h16a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2zm0 2v12h16V6H4zm2 2h12v8H6V8z"/>
                                </svg>
                                <span className="text-white font-bold text-lg">
                                  Rp {event.price.toLocaleString('id-ID')}
                                </span>
                              </div>
                              <button 
                                data-testid={`button-buy-${event.id}`}
                              >
                                <img src={tombolBeliUrl} alt="Beli" className="h-10" />
                              </button>
                            </div>
                          </div>)
                        )}
                      </div>
                    </div>
                  </Link>
                );
              })
            ) : (
              <div className="text-center text-gray-400 py-8">
                Belum ada undian aktif
              </div>
            )}
          </div>
        </div>

        {/* Rekomendasi Video */}
        <div className="px-4 py-6 bg-[#16202a]">
          <h2 className="text-xl font-bold text-white mb-4">Rekomendasi Video</h2>
          <div className="grid grid-cols-2 gap-3">
            {/* Live Card */}
            <Link href="/live">
              <div 
                data-testid="card-live"
                className="bg-gradient-to-r from-[#4DD0E1] to-[#26A69A] rounded-2xl p-5 cursor-pointer hover-elevate transition-all"
              >
                <div className="flex items-center justify-between">
                  <div className="flex flex-col gap-1">
                    <span className="text-white font-bold text-[21px]">Live</span>
                    <span className="text-white/90 text-[18px] font-normal">Lihat</span>
                  </div>
                  <div className="flex gap-2">
                    <img
                      src={thumbVideoUrl}
                      alt="Live 2"
                      className="w-28 h-28 rounded-xl object-contain"
                    />
                  </div>
                </div>
              </div>
            </Link>

            {/* Testimoni Card */}
            <Link href="/live">
              <div 
                data-testid="card-testimoni"
                className="bg-gradient-to-r from-[#7C9EF8] to-[#F48FB1] rounded-2xl p-5 cursor-pointer hover-elevate transition-all"
              >
                <div className="flex items-center justify-between">
                  <div className="flex flex-col gap-1">
                    <span className="text-white font-bold text-[21px]">Testimoni</span>
                    <span className="text-white/90 text-[18px] font-normal">Lihat</span>
                  </div>
                  <div className="flex gap-2">
                    <img
                      src={thumbTestimoniUrl}
                      alt="Testimoni 2"
                      className="w-28 h-28 rounded-xl object-contain"
                    />
                  </div>
                </div>
              </div>
            </Link>
          </div>
        </div>

        {/* Metode Pembayaran */}
        <div className="px-4 py-6 bg-[#16202a]">
          <h2 className="text-xl font-bold text-white mb-4">Metode Pembayaran</h2>
          <div className="space-y-4">
            <img
              src={bankUrl}
              alt="Payment Methods"
              className="w-full h-auto"
              data-testid="payment-methods-image"
            />
          </div>
        </div>

        <Footer />
      </div>
      <MobileBottomNav />
    </div>
  );
}

client/src/pages/admin/WinnersPage.tsx.content:
import { useQuery, useMutation } from "@tanstack/react-query";
import { AdminSidebar } from "@/components/AdminSidebar";
import { SidebarProvider, SidebarTrigger } from "@/components/ui/sidebar";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Trophy } from "lucide-react";
import { useState } from "react";
import type { Event, Transaction, Winner } from "@shared/schema";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { Card } from "@/components/ui/card";

export default function WinnersPage() {
  const [selectedEventId, setSelectedEventId] = useState<string>("");
  const [dialogOpen, setDialogOpen] = useState(false);
  const [selectedWinner, setSelectedWinner] = useState<Transaction | null>(null);
  const { toast } = useToast();

  const { data: events } = useQuery<Event[]>({
    queryKey: ["/api/admin/events"],
  });

  const { data: transactions } = useQuery<Transaction[]>({
    queryKey: ["/api/transactions"],
  });

  const { data: winners } = useQuery<Winner[]>({
    queryKey: ["/api/winners"],
  });

  const activeEvents = events?.filter(e => e.status === "aktif" || e.status === "selesai") || [];

  const eventTransactions = selectedEventId
    ? transactions?.filter(t => t.eventId === selectedEventId) || []
    : [];

  const eventWinners = selectedEventId
    ? winners?.filter(w => w.eventId === selectedEventId) || []
    : [];

  const drawWinnerMutation = useMutation({
    mutationFn: async (eventId: string) => {
      return apiRequest("/api/winners/draw", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ eventId }),
      });
    },
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["/api/winners"] });
      setSelectedWinner(data.transaction);
      setDialogOpen(true);
    },
    onError: (error: Error) => {
      toast({
        variant: "destructive",
        title: "Gagal Mengundi Pemenang",
        description: error.message,
      });
    },
  });

  const drawRandomWinner = () => {
    if (!selectedEventId) return;
    drawWinnerMutation.mutate(selectedEventId);
  };

  const confirmAnnouncement = () => {
    toast({
      title: "Pemenang Diumumkan",
      description: "Pemenang berhasil ditambahkan",
    });
    setDialogOpen(false);
    setSelectedWinner(null);
  };

  return (
    <SidebarProvider>
      <div className="flex h-screen w-full admin-light">
        <AdminSidebar />
        <div className="flex flex-col flex-1 overflow-hidden">
          <header className="flex items-center justify-between p-4 border-b bg-white">
            <SidebarTrigger data-testid="button-sidebar-toggle" />
            <h1 className="text-2xl font-bold">Nominasi Winner</h1>
            <div className="w-10" />
          </header>

          <main className="flex-1 overflow-auto p-6">
            <div className="max-w-7xl mx-auto space-y-6">
              <p className="text-gray-600">
                Pilih pemenang undian secara acak dari peserta
              </p>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium mb-2">Pilih Event</label>
                  <Select value={selectedEventId} onValueChange={setSelectedEventId}>
                    <SelectTrigger data-testid="select-event">
                      <SelectValue placeholder="Pilih event..." />
                    </SelectTrigger>
                    <SelectContent>
                      {activeEvents.map((event) => (
                        <SelectItem key={event.id} value={event.id}>
                          {event.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                {selectedEventId && (
                  <div className="flex items-end">
                    <Button
                      onClick={drawRandomWinner}
                      data-testid="button-draw-winner"
                      className="w-full bg-green-600 hover:bg-green-700"
                      disabled={eventTransactions.length === 0 || drawWinnerMutation.isPending}
                    >
                      <Trophy className="w-4 h-4 mr-2" />
                      {drawWinnerMutation.isPending ? "Mengundi..." : "Undi Pemenang"}
                    </Button>
                  </div>
                )}
              </div>

              {selectedEventId && (
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <Card className="p-4">
                    <p className="text-sm text-gray-600">Total Peserta</p>
                    <p className="text-2xl font-bold">{eventTransactions.length}</p>
                  </Card>
                  <Card className="p-4">
                    <p className="text-sm text-gray-600">Pemenang</p>
                    <p className="text-2xl font-bold text-green-600">{eventWinners.length}</p>
                  </Card>
                  <Card className="p-4">
                    <p className="text-sm text-gray-600">Sisa Peserta</p>
                    <p className="text-2xl font-bold text-blue-600">
                      {eventTransactions.length - eventWinners.length}
                    </p>
                  </Card>
                </div>
              )}

              {selectedEventId && eventWinners.length > 0 && (
                <Card className="bg-white rounded-lg border overflow-hidden">
                  <div className="p-4 border-b">
                    <h3 className="font-semibold">Daftar Pemenang</h3>
                  </div>
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>No</TableHead>
                        <TableHead>Nomor Telepon</TableHead>
                        <TableHead>Event</TableHead>
                        <TableHead>Tanggal Diumumkan</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {eventWinners.map((winner, index) => {
                        const transaction = transactions?.find(t => t.id === winner.transactionId);
                        return (
                          <TableRow key={winner.id} data-testid={`row-winner-${winner.id}`}>
                            <TableCell>{index + 1}</TableCell>
                            <TableCell className="font-medium">
                              {transaction?.phoneNumber || "-"}
                            </TableCell>
                            <TableCell>{transaction?.eventName || "-"}</TableCell>
                            <TableCell>
                              {new Date(winner.announcedAt).toLocaleDateString('id-ID', {
                                day: 'numeric',
                                month: 'long',
                                year: 'numeric',
                                hour: '2-digit',
                                minute: '2-digit'
                              })}
                            </TableCell>
                          </TableRow>
                        );
                      })}
                    </TableBody>
                  </Table>
                </Card>
              )}
            </div>
          </main>
        </div>
      </div>

      <AlertDialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Konfirmasi Pemenang</AlertDialogTitle>
            <AlertDialogDescription>
              {selectedWinner && (
                <div className="space-y-2 mt-4">
                  <p className="text-base font-semibold">Pemenang Terpilih:</p>
                  <div className="bg-gray-100 p-4 rounded">
                    <p><strong>Nomor Telepon:</strong> {selectedWinner.phoneNumber}</p>
                    <p><strong>Event:</strong> {selectedWinner.eventName}</p>
                    <p><strong>Jumlah Tiket:</strong> Rp {selectedWinner.amount.toLocaleString()}</p>
                  </div>
                  <p className="text-sm text-gray-600 mt-2">
                    Apakah Anda yakin ingin mengumumkan pemenang ini?
                  </p>
                </div>
              )}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel data-testid="button-cancel">Batal</AlertDialogCancel>
            <AlertDialogAction
              onClick={confirmAnnouncement}
              data-testid="button-confirm"
              className="bg-green-600 hover:bg-green-700"
            >
              Konfirmasi
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </SidebarProvider>
  );
}

