import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { SidebarProvider } from "@/components/ui/sidebar";
import { AdminSidebar } from "@/components/AdminSidebar";
import { AdminPageHeader } from "@/components/AdminPageHeader";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import {
  ChevronDown,
  ChevronUp,
  Upload,
  Calendar as CalendarIcon,
  Search,
  Filter,
  ArrowUpDown,
  ArrowUp,
  ArrowDown,
} from "lucide-react";
import { format } from "date-fns";
import { useToast } from "@/hooks/use-toast";

interface Event {
  id: string;
  name: string;
  imageUrl: string;
  description: string;
  price: number;
  ticketCount: number;
  ticketsReceived: number;
  prize: string;
  hadiah: number;
  startDate: string;
  endDate: string;
  announcementDate: string;
  status: string;
  category: string | null;
  cardTemplate: string | null;
  createdAt: string;
}

interface User {
  id: string;
  name: string | null;
  phoneNumber: string;
  city: string | null;
  email: string | null;
  ip: string | null;
  isActive: boolean;
  createdAt: string;
}

interface Transaction {
  id: string;
  userId: string;
  eventId: string;
  amount: number;
  ticketCount: number;
  phoneNumber: string;
  eventName: string;
  status: string;
  createdAt: string;
}

interface Winner {
  id: string;
  transactionId: string;
  eventId: string;
  userId: string;
  announcedAt: string;
}

type SortField = "name" | "phone" | "city" | "email" | "totalTickets" | "totalAmount" | "status" | "ip" | "createdAt";
type SortOrder = "asc" | "desc";

export default function EventManagerPage() {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [expandedEventId, setExpandedEventId] = useState<string | null>(null);
  const [editingEventId, setEditingEventId] = useState<string | null>(null);
  const [currentEvent, setCurrentEvent] = useState<Event | null>(null);

  const [formData, setFormData] = useState({
    name: "",
    imageUrl: "",
    description: "",
    price: "",
    ticketCount: "",
    prize: "",
    hadiah: "",
    startDate: "",
    startTime: "",
    endDate: "",
    endTime: "",
    announcementDate: "",
    announcementTime: "",
    category: "other",
  });

  const [searchTerm, setSearchTerm] = useState("");
  const [filterStatus, setFilterStatus] = useState<string[]>(["active", "inactive"]);
  const [filterEvent, setFilterEvent] = useState("all");
  const [filterWinnerStatus, setFilterWinnerStatus] = useState<string[]>(["winner", "participant"]);
  const [sortField, setSortField] = useState<SortField>("createdAt");
  const [sortOrder, setSortOrder] = useState<SortOrder>("desc");
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(10);

  const { data: events = [] } = useQuery<Event[]>({
    queryKey: ["/api/events"],
  });

  const { data: users = [] } = useQuery<User[]>({
    queryKey: ["/api/users"],
  });

  const { data: transactions = [] } = useQuery<Transaction[]>({
    queryKey: ["/api/transactions"],
  });

  const { data: winners = [] } = useQuery<Winner[]>({
    queryKey: ["/api/winners"],
  });

  const currentEvents = events.filter(e => e.status === "active");
  const pastEvents = events.filter(e => e.status === "completed");

  const createEventMutation = useMutation({
    mutationFn: async (data: FormData | Record<string, any>) => {
      const url = editingEventId ? `/api/events/${editingEventId}` : "/api/events";
      const method = editingEventId ? "PUT" : "POST";

      const isFormData = data instanceof FormData;

      const res = await fetch(url, {
        method,
        body: isFormData ? data : JSON.stringify(data),
        headers: {
          Authorization: `Bearer ${localStorage.getItem("admin_token")}`,
          ...(isFormData ? {} : { "Content-Type": "application/json" }),
        },
      });
      if (!res.ok) throw new Error(editingEventId ? "Failed to update event" : "Failed to create event");
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/events"] });
      toast({
        title: "Success",
        description: editingEventId ? "Event berhasil diupdate" : "Event berhasil dibuat",
      });
      resetForm();
    },
    onError: () => {
      toast({
        title: "Error",
        description: editingEventId ? "Gagal mengupdate event" : "Gagal membuat event",
        variant: "destructive",
      });
    },
  });

  const resetForm = () => {
    setFormData({
      name: "",
      imageUrl: "",
      description: "",
      price: "",
      ticketCount: "",
      prize: "",
      hadiah: "",
      startDate: "",
      startTime: "",
      endDate: "",
      endTime: "",
      announcementDate: "",
      announcementTime: "",
      category: "other",
    });
    setCurrentEvent(null);
    setEditingEventId(null);
  };

  const loadEventForEdit = (event: Event) => {
    const startDateTime = new Date(event.startDate);
    const endDateTime = new Date(event.endDate);
    const announcementDateTime = new Date(event.announcementDate);

    setFormData({
      name: event.name,
      imageUrl: event.imageUrl,
      description: event.description,
      price: String(event.price),
      ticketCount: String(event.ticketCount),
      prize: event.prize,
      hadiah: String(event.hadiah),
      startDate: startDateTime.toISOString().split('T')[0],
      startTime: startDateTime.toTimeString().slice(0, 5),
      endDate: endDateTime.toISOString().split('T')[0],
      endTime: endDateTime.toTimeString().slice(0, 5),
      announcementDate: announcementDateTime.toISOString().split('T')[0],
      announcementTime: announcementDateTime.toTimeString().slice(0, 5),
      category: event.category || "other",
    });
    setCurrentEvent(event);
    setEditingEventId(event.id);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const startDate = new Date(`${formData.startDate}T${formData.startTime}:00`).toISOString();
    const endDate = new Date(`${formData.endDate}T${formData.endTime}:00`).toISOString();
    const announcementDate = new Date(`${formData.announcementDate}T${formData.announcementTime}:00`).toISOString();

    const jsonData: any = {
      name: formData.name,
      imageUrl: formData.imageUrl,
      description: formData.description,
      price: Number(formData.price),
      ticketCount: Number(formData.ticketCount),
      prize: formData.prize,
      hadiah: Number(formData.hadiah),
      startDate,
      endDate,
      announcementDate,
      category: formData.category,
    };

    if (editingEventId && currentEvent) {
      jsonData.ticketsReceived = currentEvent.ticketsReceived;
      jsonData.cardTemplate = currentEvent.cardTemplate;
      jsonData.status = currentEvent.status;
    }

    createEventMutation.mutate(jsonData);
  };

  const getEventStats = (eventId: string) => {
    const eventTransactions = transactions.filter(t => t.eventId === eventId);
    const ticketsSold = eventTransactions.reduce((sum, t) => sum + t.ticketCount, 0);
    const revenue = eventTransactions.reduce((sum, t) => sum + t.amount, 0);
    const refundTotal = eventTransactions
      .filter(t => t.status === "refunded")
      .reduce((sum, t) => sum + t.amount, 0);
    const result = revenue - refundTotal;

    return { ticketsSold, revenue, refundTotal, result };
  };

  const getUserStats = (userId: string) => {
    const userTransactions = transactions.filter(t => t.userId === userId);
    const totalTickets = userTransactions.reduce((sum, t) => sum + t.ticketCount, 0);
    const totalAmount = userTransactions.reduce((sum, t) => sum + t.amount, 0);
    return { totalTickets, totalAmount };
  };

  const toggleFilterStatus = (status: string) => {
    setFilterStatus(prev => 
      prev.includes(status) 
        ? prev.filter(s => s !== status)
        : [...prev, status]
    );
    setCurrentPage(1);
  };

  const toggleFilterWinnerStatus = (status: string) => {
    setFilterWinnerStatus(prev => 
      prev.includes(status) 
        ? prev.filter(s => s !== status)
        : [...prev, status]
    );
    setCurrentPage(1);
  };

  const filteredUsers = users
    .filter(user => {
      // Search filter - jika kosong, tampilkan semua
      const matchesSearch = searchTerm === "" || 
        (user.name?.toLowerCase().includes(searchTerm.toLowerCase())) ||
        user.phoneNumber.includes(searchTerm) ||
        (user.email?.toLowerCase().includes(searchTerm.toLowerCase())) ||
        (user.city?.toLowerCase().includes(searchTerm.toLowerCase()));

      // Account status filter - jika kedua checkbox dicentang atau kosong, tampilkan semua
      const matchesAccountStatus = filterStatus.length === 0 ||
        (filterStatus.includes("active") && user.isActive) ||
        (filterStatus.includes("inactive") && !user.isActive);

      // Winner status filter - jika kedua checkbox dicentang atau kosong, tampilkan semua
      const userIsWinner = winners.some(w => w.userId === user.id);
      const matchesWinnerStatus = filterWinnerStatus.length === 0 ||
        (filterWinnerStatus.includes("winner") && userIsWinner) ||
        (filterWinnerStatus.includes("participant") && !userIsWinner);

      // Event filter
      const userHasEventTransactions = filterEvent === "all" || 
        transactions.some(t => t.userId === user.id && t.eventId === filterEvent);

      return matchesSearch && matchesAccountStatus && matchesWinnerStatus && userHasEventTransactions;
    })
    .sort((a, b) => {
      let aValue: any, bValue: any;

      switch (sortField) {
        case "name":
          aValue = (a.name || "").toLowerCase();
          bValue = (b.name || "").toLowerCase();
          break;
        case "phone":
          aValue = a.phoneNumber;
          bValue = b.phoneNumber;
          break;
        case "city":
          aValue = (a.city || "").toLowerCase();
          bValue = (b.city || "").toLowerCase();
